// ════════════════════════════════════════════
// ĐIỀN THÔNG TIN CỦA BẠN VÀO ĐÂY
// ════════════════════════════════════════════
const THREADS_USER_ID = 'ĐIỀN_USER_ID_THREADS_CỦA_BẠN';
const WEBSITE_BASE_URL = 'https://toeicmastery.vn'; // URL production của bạn
const LOCAL_URL = 'http://localhost:3000'; // URL local để chụp ảnh
// ════════════════════════════════════════════

// Chọn loại bài: 60% ảnh, 40% text
const postType = Math.random() < 0.6 ? 'image_post' : 'text_post';

// Nguồn web viral TOEIC để đọc lấy ý tưởng
const viralSources = [
  'https://study4.vn/blog',
  'https://prep.vn/toeic',
  'https://dethitoeic.com',
  'https://hochay.com/luyen-thi-toeic',
  'https://toeichanquoc.com'
];

// Các trang của website để chụp ảnh showcase
const websitePages = [
  { path: '/', label: 'Trang chủ – Luyện TOEIC toàn diện' },
  { path: '/thi-thu-mien-phi', label: 'Thi thử TOEIC miễn phí 115 câu' },
  { path: '/vocabulary', label: 'Từ vựng TOEIC 15 chủ đề' },
  { path: '/grammar', label: 'Ngữ pháp TOEIC 15 chủ đề' },
  { path: '/tu-vung', label: 'Từ vựng theo chủ đề' },
  { path: '/tips', label: 'Chiến thuật thi TOEIC' },
  { path: '/listening', label: 'Luyện Listening Part 1-4' },
  { path: '/reading', label: 'Luyện Reading Part 5-7' }
];

// Topic TOEIC viral để AI tạo content
const topics = [
  'Lỗi sai Part 5 nhiều người mắc nhất',
  'Từ vựng TOEIC chủ đề văn phòng thường gặp',
  'Chiến thuật làm Part 7 nhanh 20 phút',
  'Phân biệt despite / although / however trong TOEIC',
  'Từ vựng TOEIC chủ đề tài chính ngân hàng',
  'Cách ghi điểm Part 2 Q&A không bị bẫy',
  'Part 3 &4: kỹ thuật nghe và predict câu hỏi',
  '30 từ vựng TOEIC 900+ phải thuộc',
  'Mệnh đề quan hệ trong TOEIC Part 5',
  'Email tiếng Anh TOEIC Part 7 đọc hiểu nhanh',
  'Collocations kinh doanh thường xuất hiện trong TOEIC',
  'Part 1 ảnh tả cảnh: công thức nhận diện đáp án',
  'Phương pháp học từ vựng TOEIC bằng spaced repetition',
  'Tại sao điểm Listening luôn cao hơn Reading?',
  'Từ đồng nghĩa hay xuất hiện trong TOEIC (synonym traps)'
];

const viralSource = viralSources[Math.floor(Math.random() * viralSources.length)];
const page = websitePages[Math.floor(Math.random() * websitePages.length)];
const topic = topics[Math.floor(Math.random() * topics.length)];

return [{
  json: {
    THREADS_USER_ID,
    WEBSITE_BASE_URL,
    LOCAL_URL,
    postType,
    viralSource,
    websitePage: {
      url: LOCAL_URL + page.path,
      publicUrl: WEBSITE_BASE_URL + page.path,
      label: page.label,
      path: page.path
    },
    topic,
    timestamp: new Date().toISOString(),
    runId: Math.random().toString(36).substring(2, 8)
  }
}];

const raw = $input.first().json?.data || $input.first().json?.body || $input.first().json?.text || '';

// Strip HTML
let text = String(raw)
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"')
  .replace(/&#[0-9]+;/g, ' ')
  .replace(/\s{2,}/g, ' ')
  .trim()
  .substring(0, 2500);

if (!text || text.length < 50) {
  text = 'Không lấy được nội dung từ web. AI sẽ dùng kiến thức TOEIC chung để tạo content.';
}

return [{ json: { scrapedText: text } }];

const initData = $('⚙️ Khởi tạo dữ liệu').first().json;
const scrapedText = $('🧹 Làm sạch HTML → text').first().json?.scrapedText || '';
const imgurData = $('☁️ Upload ảnh lên Imgur').first().json;

// Lấy public URL ảnh từ Imgur
let imagePublicUrl = null;
try {
  imagePublicUrl = imgurData?.data?.link || imgurData?.link || null;
} catch (e) {}

// Fallback: nếu Imgur thất bại, dùng URL local (sẽ không dùng được cho Threads)
if (!imagePublicUrl) {
  imagePublicUrl = $('📸 Chụp ảnh giao diện web').first().json?.publicUrl || null;
}

// Nếu không có ảnh → chuyển sang text_post
const postType = imagePublicUrl ? initData.postType : 'text_post';

const websiteUrl = initData.websitePage.publicUrl;
const topic = initData.topic;

let prompt = '';
if (postType === 'image_post') {
  prompt = `Bạn là chuyên gia TOEIC người Việt với 5+ năm kinh nghiệm, đang chia sẻ kiến thức trên Threads.

Viết 1 bài Threads thu hút về: "${topic}"

Tham khảo nội dung thực tế này (đọc để hiểu trend, KHÔNG copy):
---
${scrapedText.substring(0, 2000)}
---

YÊU CẦU:
- Tối đa 450 ký tự
- Mở đầu bằng hook mạnh: câu hỏi gây tò mò HOẶC sự thật bất ngờ HOẶC thách thức
- 3-4 điểm chính với emoji (📌✅⚡💡🎯)
- Giọng văn: thân thiện, như người đã từng thi TOEIC đang chia sẻ
- KHÔNG nhắc tên website trong bài (sẽ comment link riêng)
- Kết bằng câu call-to-action nhẹ nhàng
- Thêm 3-4 hashtag cuối bài: #TOEIC #HọcTiếngAnh #TOEICMastery

Chỉ trả về nội dung bài viết.`;
} else {
  prompt = `Bạn là chuyên gia TOEIC người Việt với 5+ năm kinh nghiệm, đang chia sẻ kiến thức trên Threads.

Viết 1 bài Threads thu hút về: "${topic}"

Tham khảo nội dung thực tế này:
---
${scrapedText.substring(0, 2000)}
---

YÊU CẦU:
- Tối đa 400 ký tự (phải có link nên cần ngắn hơn)
- Mở đầu hook thu hút
- 2-3 tip cụ thể, có thể áp dụng ngay
- Dùng emoji phù hợp
- Dòng cuối: "🔗 Luyện miễn phí: ${websiteUrl}"
- Thêm hashtag: #TOEIC #HọcTiếngAnh #TOEICMastery #LuyệnThiTOEIC
- Giọng văn thật, không quảng cáo lộ liễu

Chỉ trả về nội dung bài viết.`;
}

// Comment link cho bài ảnh
const linkComment = `🔗 Học và luyện thi TOEIC miễn phí tại: ${websiteUrl}

✅ 115+ câu hỏi thực tế
✅ Từ vựng thông minh Spaced Repetition  
✅ Phân tích điểm yếu từng Part

#TOEIC #TOEICMastery #HọcTiếngAnh #LuyệnThiTOEIC`;

return [{
  json: {
    ...initData,
    postType,
    imagePublicUrl,
    prompt,
    linkComment,
    scrapedText
  }
}];

const geminiResp = $input.first().json;
const prevData = $('🔧 Chuẩn bị input cho AI').first().json;

// Extract text từ Gemini
let content = '';
try {
  content = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || '';
} catch(e) {
  content = '';
}

content = content.trim();

// Fallback content nếu Gemini thất bại
if (!content || content.length < 20) {
  content = `📚 Học TOEIC thông minh hơn với ${prevData.topic}\n\n✅ Luyện đúng phương pháp = điểm tăng nhanh\n✅ Từ vựng theo chủ đề = nhớ lâu hơn\n✅ Practice đề thật = quen format\n\nSave lại để ôn nhé! 💪\n\n#TOEIC #HọcTiếngAnh #TOEICMastery`;
}

// Đảm bảo có hashtag
if (!content.includes('#TOEIC')) {
  content += '\n\n#TOEIC #HọcTiếngAnh #TOEICMastery';
}

return [{
  json: {
    ...prevData,
    generatedContent: content,
    contentLength: content.length
  }
}];

const parsed = $('📝 Parse response Gemini').first().json;

// Lấy post ID từ nhánh nào đã chạy
let postId = 'unknown';
let status = 'Đã đăng';

try {
  const imgPost = $('🚀 Publish bài ảnh').first()?.json;
  const txtPost = $('🚀 Publish bài chữ').first()?.json;
  postId = imgPost?.id || txtPost?.id || 'N/A';
} catch(e) {
  status = 'Lỗi – ' + e.message;
}

const now = new Date(parsed.timestamp);
const vnTime = now.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

return [{
  json: {
    logTime: vnTime,
    postType: parsed.postType,
    topic: parsed.topic,
    page: parsed.websitePage?.label,
    pageUrl: parsed.websitePage?.publicUrl,
    viralSource: parsed.viralSource,
    imageUrl: parsed.imagePublicUrl || 'N/A',
    contentPreview: (parsed.generatedContent || '').substring(0, 200),
    postId,
    status,
    runId: parsed.runId
  }
}];
